#!/usr/bin/env node
const { getAllAccountEnvProps } = require("../dist/util/account-env");
const { eventRouterLint } = require("../dist/stack-components/event-router-test-support");
const yargs = require("yargs");
const rootDir = yargs.argv["root"] ?? '.';
const filename = yargs.argv["filename"] ? `${yargs.argv["filename"]}` : undefined;

(async () => {
  const allAccountEnvProps = await getAllAccountEnvProps(rootDir, filename);
  eventRouterLint(allAccountEnvProps);
})();